def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

    Args:
        M (int): The number of rows in the classroom.
        N (int): The number of columns in the classroom.
        K (int): The number of horizontal aisles to add.
        L (int): The number of vertical aisles to add.
        D (int): The number of chatting pairs in the classroom.
        chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.

    Returns:
        (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.
    """
    # Initialize the adjacency matrix of the graph
    adj_matrix = [[0 for _ in range(N + K)] for _ in range(M + L)]

    # Fill the adjacency matrix with the edges of the graph
    for (Xi, Yi), (Pi, Qi) in chatting_pairs:
        adj_matrix[Xi + L][Yi + N] = 1
        adj_matrix[Pi + L][Qi + N] = 1

    # Find the strongly connected components of the graph
    components = []
    for i in range(M + L):
        for j in range(N + K):
            if adj_matrix[i][j] == 0:
                continue
            if i < M and j < N:
                components.append((i, j))
            elif i < M and j >= N:
                components.append((i, j - N))
            elif i >= M and j < N:
                components.append((i - M, j))
            else:
                components.append((i - M, j - N))

    # Create a new array to store the number of chatting pairs in each component
    num_chatting_pairs = [0] * len(components)

    # Count the number of chatting pairs in each component
    for (Xi, Yi), (Pi, Qi) in chatting_pairs:
        for i in range(len(components)):
            if Xi + L in range(components[i][0], components[i][0] + M + L) and Yi + N in range(components[i][1], components[i][1] + N + K):
                num_chatting_pairs[i] += 1
            elif Pi + L in range(components[i][0], components[i][0] + M + L) and Qi + N in range(components[i][1], components[i][1] + N + K):
                num_chatting_pairs[i] += 1

    # Find the optimal aisle positions for the strongly connected components
    for i in range(len(components)):
        if num_chatting_pairs[i] == 0:
            continue
        optimal_position = components[i]
        for j in range(i + 1, len(components)):
            if (optimal_position[0] - optimal_position[1] == components[j][0] - components[j][1] and
                optimal_position[1] + K == components[j][1]):
                num_chatting_pairs[j] = 0
                optimal_position = components[j]

    # Transform the indices to strings
    optimal_row_idx = str(optimal_position[0] - M)
    optimal_col_idx = " ".join(str(optimal_position[1]) for _ in range(N + K))
    return (optimal_row_idx, optimal_col_idx)

