    max_val_and_indices = [-1, []]

    # Calculate the maximum total importance value for each possible combination of items
    for i in range(1 << m):
        total_val = 0
        indices = []
        for j in range(m):
            if i & (1 << j):
                total_val += items[j][1]
                indices.append(j)
        if total_val <= n:
            if total_val > max_val_and_indices[0]:
