def max_energy(beads):
    # Initialize a dictionary to store the maximum energy for each length of beads
    max_energy = {0: 0, 1: beads[0]}

    # Iterate through each length of beads
    for i in range(1, len(beads)):
        # Calculate the maximum energy for the current length of beads
        max_energy[i] = max(max_energy[i - 1] * beads[i], beads[i] * max_energy[i - 1])

    # Return the maximum energy for the entire necklace
    return max_energy[len(beads) - 1]

