def decode(encoded, original, message):
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    :param encoded: A string representing the encoded information.
    :param original: A string representing the original information corresponding to the encoded string.
    :param message: A string representing the encrypted message to be decoded.
    :return: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Build a dictionary mapping encoded letters to their original letters
    encoded_to_original = {}
    for i, char in enumerate(original):
        encoded_to_original[encoded[i]] = char

    # Check for contradictions and make sure all letters are represented
    for char in message:
        if char not in encoded_to_original:
            return "Failed"
        if encoded_to_original[char] in encoded_to_original.values():
            return "Failed"

    # Construct the decoding mapping and decode the message
    decoding_mapping = {}
    for char in message:
        decoding_mapping[char] = encoded_to_original[char]
    return "".join([decoding_mapping[char] for char in message])

