def count_sequences(n, last, memo):
    # Initialize the memoization dictionary if it has not been created yet
    if memo == {}:
        memo = {last: 1}
    # If the input number is greater than the maximum possible value,
    # there are no valid sequences
    if n > (last//2) + 1:
        return 0
    # Check if the memoization dictionary already contains a count for the input number
    if n in memo:
        return memo[n]
    # Calculate the number of valid sequences for the current number
    else:
        count = 0
        for i in range(max(0, n-last), min((last//2)+1, n)+1):
            count += count_sequences(i, last, memo)
    # Store the count for the input number in the memoization dictionary
    memo[n] = count
    return count

