def generate_numbers(n, rules):

    visited = set()
    queue = [(n, [])]

    while queue:
        number, transformation = queue.pop(0)
        visited.add(number)

        for digit in str(number):
            for trans in rules:
                if digit == trans[0]:
                    new_number = number.replace(digit, trans[1], 1)
                    if new_number not in visited:
                        queue.append((new_number, transformation + [digit]))

    return len(visited)

def generate_numbers(n, rules):
