def minimum_students_to_leave(heights):

    # Create two lists for the increasing and decreasing heights
    increasing_heights = []
    decreasing_heights = []
    for i in range(len(heights)):
        if i == 0:
            increasing_heights.append(heights[i])
        elif heights[i] > heights[i-1]:
            increasing_heights.append(heights[i])
        else:
            decreasing_heights.append(heights[i])

    # Find the minimum number of students that need to leave
    # for the increasing heights
    min_inc = len(increasing_heights)
    for i in range(len(increasing_heights)):
        if increasing_heights[i] > increasing_heights[i-1]:
            min_inc = min(min_inc, len(increasing_heights)-i)

    # Find the minimum number of students that need to leave
    # for the decreasing heights
    min_dec = len(decreasing_heights)
    for i in range(len(decreasing_heights)):
        if decreasing_heights[i] < decreasing_heights[i-1]:
            min_dec = min(min_dec, len(decreasing_heights)-i)

    # Return the minimum number of students that need to leave
    return min(min_inc, min_dec)

